// M1: ADD TOOL #91 TO ALLOWLIST
// ══════════════════════════════════════════════════════════════════
function m1_addToAllowlist() {
  console.log('\n[M1] Adding sous-vide-pouch-delamination-modeler to consumer-tools-allowlist.json…');
  const listPath = 'src/data/consumer-tools-allowlist.json';
  const list = readJSON(listPath);
  const slug = 'sous-vide-pouch-delamination-modeler';
  if (!list.includes(slug)) {
    list.push(slug);
    writeJSON(listPath, list);
    console.log(`    ✓ Added ${slug} (now ${list.length} tools)`);
  } else {
    console.log(`    ⚡ Already present (${list.length} tools)`);
  }
  return list.length;
}

