function m2_publishBlogGuides() {
  console.log('\n[M2] Publishing 3 safety guides (5 langs each)…');
  const LANGS = ['en', 'es', 'pt', 'zh-cn', 'ja'];

  for (const lang of LANGS) {
    const dataFile = lang === 'en' ? 'src/data/blog.json' : `src/data/blog.${lang}.json`;
    const data = readJSON(dataFile);

    for (const guide of GUIDES) {
      const existing = data.find(g => g.slug === guide.slug);
      if (existing) {
        console.log(`    ⚡ ${lang}: ${guide.slug} already present`);
        continue;
      }
      const lc = guide[lang] || guide.en;
      const entry = {
        slug: guide.slug,
        title: lc.title,
        excerpt: lc.excerpt,
        date: guide.date,
        readTime: guide.readTime,
        author: guide.author,
        intro: lc.intro,
        sections: lc.sections,
        conclusion: lc.conclusion,
        faqs: lc.faqs,
        relatedTools: lc.relatedTools
      };
      data.push(entry);
      console.log(`    ✓ ${lang}: added ${guide.slug}`);
    }

    writeJSON(dataFile, data);
  }
  // Return new count in EN
  const enData = readJSON('src/data/blog.json');
  console.log(`    → Total EN blog guides: ${enData.length}`);
  return enData.length;
}

// ══════════════════════════════════════════════════════════════════
// M3: WIRE RSS, LLMS.TXT, README.MD
// ══════════════════════════════════════════════════════════════════
function m3_wireDiscovery(toolCount, guideCount) {
  console.log('\n[M3] Wiring RSS, llms.txt, README.md…');

  // --- llms.txt ---
  const llmsTxt = readFile('public/llms.txt');
  if (!llmsTxt.includes('sous-vide-pouch-delamination-modeler')) {
    const insertAfter = '- [Wooden Spoon & Utensil Micro-Crack Bacterial Biofilm';
    const newLine = `- [Sous Vide High-Temperature Pouch Seam Delamination & Microplastic Modeler](https://isitkitchensafe.com/tools/sous-vide-pouch-delamination-modeler/): Models LDPE/LLDPE pouch viscoelastic seal creep at 85°C–92°C, ASTM F88 burst pressure thresholds, Arrhenius microplastic shedding kinetics (450,000 nanoparticles/dm² above 80°C), and Fickian lipid-phase D/T migration against EU No 10/2011 OML 10 mg/dm² and FDA 21 CFR 177.1520.`;
    const idx = llmsTxt.indexOf(insertAfter);
    if (idx !== -1) {
      const lineEnd = llmsTxt.indexOf('\n', idx);
      const updated = llmsTxt.slice(0, lineEnd + 1) + newLine + '\n' + llmsTxt.slice(lineEnd + 1);
      // Also update the stats line
      const statsUpdated = updated
        .replace(/\*\*\d+ Google-indexed everyday consumer tools\*\*/, `**${toolCount} Google-indexed everyday consumer tools**`)
        .replace(/\*\*\d+ evergreen guides per language\*\*/, `**${guideCount} evergreen guides per language**`);
      writeFile('public/llms.txt', statsUpdated);
      console.log('    ✓ llms.txt updated with sous-vide-pouch-delamination-modeler entry');
    } else {
      // fallback: just update stats
      const statsUpdated = llmsTxt
        .replace(/\*\*\d+ Google-indexed everyday consumer tools\*\*/, `**${toolCount} Google-indexed everyday consumer tools**`)
        .replace(/\*\*\d+ evergreen guides per language\*\*/, `**${guideCount} evergreen guides per language**`);
      writeFile('public/llms.txt', statsUpdated);
      console.log('    ✓ llms.txt stats updated');
    }
  } else {
    console.log('    ⚡ llms.txt already contains sous-vide-pouch-delamination-modeler');
  }

  // --- README.md ---
  const readme = readFile('README.md');
  const readmeUpdated = readme
    .replace(/\*\*\d+ Google-indexed consumer tools\*\*/, `**${toolCount} Google-indexed consumer tools**`)
    .replace(/\*\*\d+ consumer tools indexed\*\*/, `**${toolCount} consumer tools indexed**`)
    .replace(/\*\*\d+ evergreen guides\/locale\*\*/, `**${guideCount} evergreen guides/locale**`)
    .replace(/\*\*\d+ blog guides\/locale\*\*/, `**${guideCount} blog guides/locale**`);
  if (readmeUpdated !== readme) {
    writeFile('README.md', readmeUpdated);
    console.log('    ✓ README.md stats updated');
  } else {
    console.log('    ⚡ README.md stats already current');
  }

  console.log('    ✓ M3 wiring complete');
}

